import com.badlogic.gdx.utils.Array;
import com.badlogic.gdx.utils.Disposable;
import com.badlogic.gdx.utils.Pool;
import com.badlogic.gdx.utils.SortedIntList;
import com.uber.nullaway.annotations.Initializer;
import javax.annotation.Nullable;

/**
 * Renderer for {@link Decal} objects.
 *
 * <p>New objects are added using {@link DecalBatch#add(Decal)}, there is no limit on how many
 * decals can be added.<br>
 * Once all the decals have been submitted a call to {@link DecalBatch#flush()} will batch them
 * together and send big chunks of geometry to the GL.
 *
 * <p>The size of the batch specifies the maximum number of decals that can be batched together
 * before they have to be submitted to the graphics pipeline. The default size is {@link
 * DecalBatch#DEFAULT_SIZE}. If it is known before hand that not as many will be needed on average
 * the batch can be downsized to save memory. If the game is basically 3d based and decals will only
 * be needed for an orthogonal HUD it makes sense to tune the size down.
 *
 * <p>The way the batch handles things depends on the {@link GroupStrategy}. Different strategies
 * can be used to customize shaders, states, culling etc. for more details see the {@link
 * GroupStrategy} java doc.<br>
 * While it shouldn't be necessary to change strategies, if you have to do so, do it before calling
 * {@link #add(Decal)}, and if you already did, call {@link #flush()} first.
 */
public class DecalBatch implements Disposable {
  private static final int DEFAULT_SIZE = 1000;
  private float[] vertices;
  private Mesh mesh;

  private final SortedIntList<Array<Decal>> groupList = new SortedIntList<Array<Decal>>();
  @Nullable private GroupStrategy groupStrategy;
  private final Pool<Array<Decal>> groupPool =
      new Pool<Array<Decal>>(16) {
        @Override
        protected Array<Decal> newObject() {
          return new Array<Decal>(false, 100);
        }
      };
  private final Array<Array<Decal>> usedGroups = new Array<Array<Decal>>(16);

  /**
   * Creates a new DecalBatch using the given {@link GroupStrategy}. The most commong strategy to
   * use is a {@link CameraGroupStrategy}
   *
   * @param groupStrategy
   */
  public DecalBatch(GroupStrategy groupStrategy) {
    this(DEFAULT_SIZE, groupStrategy);
  }

  public DecalBatch(int size, GroupStrategy groupStrategy) {
    initialize(size);
    setGroupStrategy(groupStrategy);
  }

  /**
   * Sets the {@link GroupStrategy} used
   *
   * @param groupStrategy Group strategy to use
   */
  public void setGroupStrategy(GroupStrategy groupStrategy) {
    this.groupStrategy = groupStrategy;
  }

  /**
   * Initializes the batch with the given amount of decal objects the buffer is able to hold when
   * full.
   *
   * @param size Maximum size of decal objects to hold in memory
   */
  @Initializer
  public void initialize(int size) {
    vertices = new float[size * Decal.SIZE];

    Mesh.VertexDataType vertexDataType = Mesh.VertexDataType.VertexArray;
    if (Gdx.gl30 != null) {
      vertexDataType = Mesh.VertexDataType.VertexBufferObjectWithVAO;
    }
    mesh =
        new Mesh(
            vertexDataType,
            false,
            size * 4,
            size * 6,
            new VertexAttribute(
                VertexAttributes.Usage.Position, 3, ShaderProgram.POSITION_ATTRIBUTE),
            new VertexAttribute(
                VertexAttributes.Usage.ColorPacked, 4, ShaderProgram.COLOR_ATTRIBUTE),
            new VertexAttribute(
                VertexAttributes.Usage.TextureCoordinates,
                2,
                ShaderProgram.TEXCOORD_ATTRIBUTE + "0"));

    short[] indices = new short[size * 6];
    int v = 0;
    for (int i = 0; i < indices.length; i += 6, v += 4) {
      indices[i] = (short) (v);
      indices[i + 1] = (short) (v + 2);
      indices[i + 2] = (short) (v + 1);
      indices[i + 3] = (short) (v + 1);
      indices[i + 4] = (short) (v + 2);
      indices[i + 5] = (short) (v + 3);
    }
    mesh.setIndices(indices);
  }

  /**
   * @return maximum amount of decal objects this buffer can hold in memory
   */
  public int getSize() {
    return vertices.length / Decal.SIZE;
  }

  /**
   * Add a decal to the batch, marking it for later rendering
   *
   * @param decal Decal to add for rendering
   */
  public void add(Decal decal) {
    if (groupStrategy == null) {
      throw new IllegalStateException("GroupStrategy must be set before adding decals.");
    }
    int groupIndex = groupStrategy.decideGroup(decal);
    Array<Decal> targetGroup = groupList.get(groupIndex);
    if (targetGroup == null) {
      targetGroup = groupPool.obtain();
      targetGroup.clear();
      usedGroups.add(targetGroup);
      groupList.insert(groupIndex, targetGroup);
    }
    targetGroup.add(decal);
  }

  // ... rest of original DecalBatch methods unchanged ...
}
